    head.next = &a; a.next = &b; b.next = &c; c.next = &d; d.next = &head;
    head.prev = &d; d.prev = &c; c.prev = &b; b.prev = &a; a.prev = &head;
    a.item = &x; b.item = 0; c.item = 0; d.item = &y; head.item = 0;
